#!/usr/bin/env node
/**
 * Stages web assets for Capacitor.
 *
 * TanStack Start + Nitro (Vercel preset) outputs static files to
 * `.vercel/output/static` and does NOT emit a root index.html
 * (HTML is generated by the SSR server).
 *
 * This script:
 * 1. Copies `.vercel/output/static` → `dist/`
 * 2. If no index.html exists, creates a minimal bootstrap page
 *    that loads the main client bundle so Capacitor has something
 *    to display.
 */

import { cpSync, existsSync, mkdirSync, readdirSync, writeFileSync, rmSync } from 'node:fs';
import { join } from 'node:path';

const ROOT = process.cwd();
const STATIC_SRC = join(ROOT, '.vercel', 'output', 'static');
const DIST = join(ROOT, 'dist');

function fail(msg) {
  console.error(`[stage-capacitor] ${msg}`);
  process.exit(1);
}

if (!existsSync(STATIC_SRC)) {
  fail(
    `Static output not found at ${STATIC_SRC}.\n` +
      'Run `npm run build:dev` (or `npm run build`) first.',
  );
}

// Clean + copy
if (existsSync(DIST)) {
  rmSync(DIST, { recursive: true, force: true });
}
mkdirSync(DIST, { recursive: true });
cpSync(STATIC_SRC, DIST, { recursive: true });
console.log(`[stage-capacitor] Copied ${STATIC_SRC} → dist/`);

const indexPath = join(DIST, 'index.html');

if (!existsSync(indexPath)) {
  // Find the main client entry (largest JS in assets/ that looks like the app bundle)
  const assetsDir = join(DIST, 'assets');
  let entryScript = null;

  if (existsSync(assetsDir)) {
    const files = readdirSync(assetsDir).filter((f) => f.endsWith('.js'));
    // Prefer files named index-*.js or the largest one
    const indexLike = files.find((f) => f.startsWith('index-'));
    if (indexLike) {
      entryScript = `assets/${indexLike}`;
    } else if (files.length > 0) {
      // fallback: pick the biggest JS file
      const { statSync } = await import('node:fs');
      files.sort((a, b) => statSync(join(assetsDir, b)).size - statSync(join(assetsDir, a)).size);
      entryScript = `assets/${files[0]}`;
    }
  }

  const cssFiles = existsSync(join(DIST, 'assets'))
    ? readdirSync(join(DIST, 'assets')).filter((f) => f.endsWith('.css'))
    : [];

  const cssLinks = cssFiles
    .map((f) => `    <link rel="stylesheet" href="assets/${f}">`)
    .join('\n');

  const scriptTag = entryScript
    ? `    <script type="module" src="${entryScript}"></script>`
    : '    <!-- no client entry found -->';

  const html = `<!DOCTYPE html>
<html lang="ru">
  <head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover" />
    <meta name="theme-color" content="#0a0a0b" />
    <title>Nexora</title>
    <link rel="icon" type="image/svg+xml" href="/favicon.svg" />
${cssLinks}
  </head>
  <body class="bg-bg font-sans text-fg">
    <div id="root"></div>
${scriptTag}
  </body>
</html>
`;

  writeFileSync(indexPath, html, 'utf8');
  console.log(`[stage-capacitor] Created bootstrap index.html (entry: ${entryScript ?? 'none'})`);
} else {
  console.log('[stage-capacitor] index.html already present');
}

console.log('[stage-capacitor] Ready. Run `npx cap sync android` next.');
